import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

ln_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor layernorm_forward(torch::Tensor x,
                                torch::Tensor weight,
                                torch::Tensor bias,
                                double eps);
"""

ln_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// One fused LayerNorm kernel.
// Each block normalizes one full "row" of length L (L = numel(normalized_shape)).
// Pass 1: block-cooperative reduction of sum / sum-of-squares.
// Pass 2: normalize + elementwise affine (gamma, beta).
template <int Threads, int Vec>
__global__ void layernorm_fwd_kernel(
    const float* __restrict__ X,
    const float* __restrict__ G,
    const float* __restrict__ B,
    float* __restrict__ Y,
    int64_t L,
    float eps)
{
  const int64_t row = blockIdx.x;
  const int     tid = threadIdx.x;

  const int64_t row_off = row * L;
  const int64_t Nv      = L / Vec;           // number of full vectors
  const int64_t tail0   = Nv * Vec;          // start of scalar tail

  // CuTe global-memory tensors (vectorized views)
  Tensor gX = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(X + row_off)),
                          make_shape(Nv));
  Tensor gG = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(G)),
                          make_shape(Nv));
  Tensor gB = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(B)),
                          make_shape(Nv));
  Tensor gY = make_tensor(make_gmem_ptr(reinterpret_cast<float4*>(Y + row_off)),
                          make_shape(Nv));

  // ---- Pass 1: thread-local partial sums (strided over the row) ----
  float s  = 0.0f;
  float sq = 0.0f;
  for (int64_t i = tid; i < Nv; i += Threads) {
    float4 v = gX(i);
    s  += v.x + v.y + v.z + v.w;
    sq += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
  }
  // scalar tail (L not divisible by Vec)
  for (int64_t i = tail0 + tid; i < L; i += Threads) {
    float v = X[row_off + i];
    s  += v;
    sq += v * v;
  }

  // ---- Block reduction using warp shuffles ----
  constexpr int Warps = Threads / 32;
  __shared__ float warp_s[Warps];
  __shared__ float warp_q[Warps];
  __shared__ float sh_mean;
  __shared__ float sh_rstd;
  const int lane = tid & 31;
  const int warp = tid >> 5;
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    s  += __shfl_down_sync(0xffffffffu, s,  off);
    sq += __shfl_down_sync(0xffffffffu, sq, off);
  }
  if (lane == 0) {
    warp_s[warp] = s;
    warp_q[warp] = sq;
  }
  __syncthreads();
  if (warp == 0) {
    float ws = (lane < Warps) ? warp_s[lane] : 0.0f;
    float wq = (lane < Warps) ? warp_q[lane] : 0.0f;
    #pragma unroll
    for (int off = Warps / 2; off > 0; off >>= 1) {
      ws += __shfl_down_sync(0xffffffffu, ws, off);
      wq += __shfl_down_sync(0xffffffffu, wq, off);
    }
    if (lane == 0) {
      float invL = 1.0f / (float)L;
      float mean = ws * invL;
      float var  = wq * invL - mean * mean;
      var = var < 0.0f ? 0.0f : var;
      sh_mean = mean;
      sh_rstd = rsqrtf(var + eps);
    }
  }
  __syncthreads();
  const float mean = sh_mean;
  const float rstd = sh_rstd;

  // ---- Pass 2: normalize + affine, vectorized via CuTe tensors ----
  for (int64_t i = tid; i < Nv; i += Threads) {
    float4 xv = gX(i);
    float4 gv = gG(i);
    float4 bv = gB(i);
    float4 ov;
    ov.x = (xv.x - mean) * rstd * gv.x + bv.x;
    ov.y = (xv.y - mean) * rstd * gv.y + bv.y;
    ov.z = (xv.z - mean) * rstd * gv.z + bv.z;
    ov.w = (xv.w - mean) * rstd * gv.w + bv.w;
    gY(i) = ov;
  }
  // scalar tail
  for (int64_t i = tail0 + tid; i < L; i += Threads) {
    Y[row_off + i] = (X[row_off + i] - mean) * rstd * G[i] + B[i];
  }
}

torch::Tensor layernorm_forward(torch::Tensor x,
                                torch::Tensor weight,
                                torch::Tensor bias,
                                double eps)
{
  TORCH_CHECK(x.is_cuda() && weight.is_cuda() && bias.is_cuda(),
              "x, weight and bias must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat &&
              weight.scalar_type() == at::kFloat &&
              bias.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  auto b_c = bias.contiguous();

  const int64_t L = w_c.numel();
  TORCH_CHECK(L > 0, "normalized_shape numel must be > 0");
  TORCH_CHECK(b_c.numel() == L, "bias numel must match weight numel");
  TORCH_CHECK(x_c.numel() % L == 0,
              "input numel must be divisible by normalized numel");
  const int64_t rows = x_c.numel() / L;

  auto y = torch::empty_like(x_c);

  constexpr int Threads = 512;
  constexpr int Vec     = 4;

  dim3 grid((unsigned)rows);
  dim3 block(Threads);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  layernorm_fwd_kernel<Threads, Vec><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_c.data_ptr<float>(),
      y.data_ptr<float>(),
      L,
      (float)eps);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "layernorm_fwd_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=ln_cpp_decl,
    cuda_sources=ln_cuda_src,
    functions=["layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Layer Normalization implemented with a single fused custom CUDA kernel
    using CuTe tensors (block-cooperative reduction + vectorized normalize).
    """
    def __init__(self, normalized_shape) -> None:
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5

        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))

        self._ext = layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.layernorm_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias.contiguous(),
            float(self.eps),
        )

